  "Mukunthan K U": "+91 9380180076",
  "Rajakarthikeyan R": "+91 8431942480",
  "Srushti Shewalkar": "+91 7498400618",
};

const managerName = String($json.Manager ?? "")
  .trim()
  .replace(/\s+/g, " ")
  .toLowerCase();

const matchedName = Object.keys(managers).find(
  name => name.toLowerCase() === managerName
);

if (!matchedName) {
  throw new Error(
    `Unknown or missing manager: "${$json.Manager ?? ""}". Check the Manager column in Google Sheets.`
  );
}

const phone = managers[matchedName];

const emailSignature =
  `<b>${matchedName}</b><br>` +
  `<b>Manager | Corporate Relations</b><br>` +
  `<b>Entrepreneurship-Cell, IIT Madras</b><br>` +
  `<b>Email: <a href="mailto:corporate_ecell@smail.iitm.ac.in">corporate_ecell@smail.iitm.ac.in</a></b><br>` +
  `<b>Ph: ${phone}</b>`;

return {
  ...$json,
  managerName: matchedName,
  managerPhone: phone,
  emailSignature,
};

